// ==============================================================================
// ZYRVAE WF-02: Control de Modo y Parsing de Entrada
// ==============================================================================
// MODO PREDETERMINADO: PRUEBA AISLADA (Seguridad estricta)
// true  = Ejecuta prueba sintética aislada (omite WF-01 y Data Tables por completo)
// false = Modo Producción (exige archivo CSV binario y escribe en producción)
const RUN_SYNTHETIC_TEST = true;

const items = $input.all();
let csvText = '';
let isSyntheticTest = RUN_SYNTHETIC_TEST;

if (isSyntheticTest) {
  csvText = `business_name,website_url,country,industry,source,source_url,evidence_notes
"[TEST-01] Valid Tech Corp",https://example.com,AR,Technology,CSV_TEST,https://test.zyrvae.internal/leads.csv,"Valid test lead"
"[TEST-02] Broken Server SA",https://httpbin.org/status/503,CL,Retail,CSV_TEST,https://test.zyrvae.internal/leads.csv,"HTTP 503 test"
"[TEST-03] Malformed Lead",not-a-valid-domain,UY,Consulting,CSV_TEST,https://test.zyrvae.internal/leads.csv,"Malformed URL"
"[TEST-04] Duplicate Tech Corp",https://example.com,AR,Technology,CSV_TEST,https://test.zyrvae.internal/leads.csv,"Duplicate test"
"",,,,,"Empty row test"
"[TEST-05] SSRF Trap Inc",http://127.0.0.1:8080/admin,MX,Security,CSV_TEST,https://test.zyrvae.internal/leads.csv,"SSRF test"`;
} else {
  if (items[0] && items[0].binary) {
    const binKeys = Object.keys(items[0].binary);
    if (binKeys.length > 0 && items[0].binary[binKeys[0]].data) {
      csvText = Buffer.from(items[0].binary[binKeys[0]].data, 'base64').toString('utf8');
    }
  } else if (items[0] && items[0].json && typeof items[0].json.csv_data === 'string' && items[0].json.csv_data.trim()) {
    csvText = items[0].json.csv_data.trim();
  } else {
    throw new Error(
      'ZYRVAE WF-02 (Producción): No se detectó ningún archivo CSV binario ni contenido en csv_data. ' +
      'Para procesar datos reales, adjunte un archivo CSV. ' +
      'Para pruebas seguras, active RUN_SYNTHETIC_TEST = true en el código.'
    );
  }
}

function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter(line => line.trim().length > 0);
  if (lines.length === 0) return { headers: [], rows: [] };

  function splitRow(rowStr) {
    const regex = /(?:"([^"]*(?:""[^"]*)*)"|([^,]+)|(?=,))(?:,|$)/g;
    const result = [];
    let match;
    while ((match = regex.exec(rowStr)) !== null) {
      if (match.index === regex.lastIndex) regex.lastIndex++;
      let val = match[1] !== undefined ? match[1].replace(/""/g, '"') : (match[2] !== undefined ? match[2] : '');
      result.push(val.trim());
      if (regex.lastIndex >= rowStr.length && rowStr.endsWith(',')) {
        result.push('');
        break;
      }
    }
    return result;
  }

  const rawHeaders = splitRow(lines[0]).map(h => h.toLowerCase().trim());
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const values = splitRow(lines[i]);
    const rowObj = {};
    rawHeaders.forEach((h, idx) => {
      rowObj[h] = values[idx] || '';
    });
    rows.push({ rowIndex: i + 1, data: rowObj });
  }
  return { headers: rawHeaders, rows };
}

const parsed = parseCSV(csvText);
const validProspects = [];
const skippedErrors = [];
const seenUrls = new Set();

for (const row of parsed.rows) {
  const bName = (row.data.business_name || '').trim();
  let wUrl = (row.data.website_url || '').trim();

  if (!bName && !wUrl) {
    skippedErrors.push({ row: row.rowIndex, error: 'EMPTY_ROW', reason: 'Fila sin nombre ni web', raw: row.data });
    continue;
  }
  if (!bName) {
    skippedErrors.push({ row: row.rowIndex, error: 'MISSING_BUSINESS_NAME', reason: 'Nombre de empresa ausente', raw: row.data });
    continue;
  }
  if (wUrl) {
    if (!wUrl.startsWith('http://') && !wUrl.startsWith('https://')) {
      if (wUrl.includes('.') && !wUrl.includes(' ')) {
        wUrl = 'https://' + wUrl;
      } else {
        skippedErrors.push({ row: row.rowIndex, error: 'INVALID_URL_SYNTAX', reason: 'Sintaxis de URL inválida', raw: row.data });
        continue;
      }
    }
  }

  const normUrl = wUrl.toLowerCase().replace(/\/+$/, '');
  if (normUrl && seenUrls.has(normUrl)) {
    skippedErrors.push({ row: row.rowIndex, error: 'IN_BATCH_DUPLICATE', reason: 'URL duplicada dentro del archivo CSV', raw: row.data });
    continue;
  }
  if (normUrl) seenUrls.add(normUrl);

  validProspects.push({
    json: {
      row_index: row.rowIndex,
      business_name: bName,
      website_url: wUrl,
      country: (row.data.country || '').trim(),
      industry: (row.data.industry || '').trim(),
      source: (row.data.source || (isSyntheticTest ? 'CSV_TEST' : 'CSV_IMPORT')).trim(),
      source_url: (row.data.source_url || '').trim(),
      evidence_notes: (row.data.evidence_notes || '').trim(),
      is_synthetic_test: isSyntheticTest,
      batch_id: $execution.id || 'manual-batch'
    }
  });
}

return validProspects;

// ==============================================================================
// Mock WF-01 Response: Genera IDs sintéticos no reutilizables sin invocar WF-01
// ==============================================================================
const item = $input.item.json;
const timestamp = Date.now().toString(36);
const synthProspectId = `SYNTH-PROSPECT-${item.row_index}-${timestamp}-TESTONLY`;

return {
  json: {
    ...item,
    prospect_id: synthProspectId,
    lead_key: synthProspectId,
    normalized_business_name: item.business_name,
    normalized_website_url: item.website_url,
    status: 'MOCK_SYNTHETIC_PROCESSED',
    wf01_executed_live: false
  }
};

// ==============================================================================
// Adaptador de Contrato WF-01: Extraer ID estable (lead_key) y mapear prospecto
// ==============================================================================
const wf01Result = $input.item.json;
let prospect = {};
try {
  prospect = $('Loop Over Prospects (Sequential)').item.json;
} catch (e) {
  prospect = $('Loop Over Prospects (Sequential)').first().json || {};
}

const records = wf01Result.records || [];
const record = records[0] || {};
const leadKey = record.lead_key;

if (!leadKey) {
  const errorMsg = (wf01Result.errors && wf01Result.errors[0] && wf01Result.errors[0].error_message)
    || (record.error_message)
    || 'WF-01 did not return a valid lead_key for prospect';
  throw new Error(`WF-01 Contract Failure: ${errorMsg}`);
}

return {
  json: {
    ...prospect,
    prospect_id: leadKey,
    lead_key: leadKey,
    wf01_outcome: record.outcome || 'unknown',
    wf01_status: record.final_status || 'unknown',
    wf01_validation_issues: record.validation_issues || '',
    wf01_executed_live: true,
    normalized_website_url: prospect.website_url,
    normalized_business_name: record.business_name || prospect.business_name
  }
};

// ==============================================================================
// SSRF & Safety Guard: Bloquea destinos locales, privados o metadata
// Se ejecuta OBLIGATORIAMENTE tanto en pruebas como en producción
// ==============================================================================
const item = $input.item.json;
const urlStr = item.normalized_website_url || item.website_url;

function checkSSRF(url) {
  if (!url) return { safe: false, reason: 'URL ausente' };
  try {
    const match = url.match(/^([a-zA-Z]+):\/\/([^/:]+)(?::(\d+))?(\/.*)?$/);
    if (!match) return { safe: false, reason: 'Formato de URL inválido' };
    const protocol = match[1].toLowerCase();
    if (protocol !== 'http' && protocol !== 'https') {
      return { safe: false, reason: `Protocolo no permitido: ${protocol}` };
    }
    const host = match[2].toLowerCase().replace(/^\[|\]$/g, '');
    if (['localhost', '127.0.0.1', '::1', '0.0.0.0', 'metadata.google.internal'].includes(host)) {
      return { safe: false, reason: 'Host de loopback / cloud metadata bloqueado' };
    }
    if (host.startsWith('10.') || host.startsWith('192.168.') || host.startsWith('169.254.')) {
      return { safe: false, reason: 'Red privada / cloud metadata bloqueada' };
    }
    if (host.match(/^172\.(1[6-9]|2[0-9]|3[0-1])\./)) {
      return { safe: false, reason: 'Red privada RFC 1918 bloqueada' };
    }
    if (host.startsWith('fc') || host.startsWith('fe80') || host.includes('::ffff:')) {
      return { safe: false, reason: 'Red IPv6 local o privada bloqueada' };
    }
    return { safe: true, reason: null };
  } catch (e) {
    return { safe: false, reason: 'Error validando SSRF: ' + (e && e.message ? e.message : String(e)) };
  }
}

const check = checkSSRF(urlStr);

if (!item.prospect_id) {
  if (item.is_synthetic_test) {
    item.prospect_id = `SYNTH-PROSPECT-${item.row_index || 1}-${Date.now().toString(36)}-TESTONLY`;
  } else {
    throw new Error('SSRF Guard: Falta el prospect_id estable para un prospecto de producción.');
  }
}

return {
  json: {
    ...item,
    prospect_id: item.prospect_id,
    lead_key: item.lead_key || item.prospect_id,
    audit_target_url: urlStr,
    is_ssrf_safe: check.safe,
    ssrf_block_reason: check.reason
  }
};

// ==============================================================================
// Extraer evidencia técnica objetiva y formular hipótesis comerciales factibles
// ==============================================================================
const item = $input.item.json;
let prospectData = {};
try {
  prospectData = $('SSRF Security Filter').item.json;
} catch (e) {
  prospectData = $('SSRF Security Filter').first().json || {};
}

const statusCode = item.statusCode || item.status || null;
const headers = item.headers || {};
const body = typeof item.body === 'string' ? item.body : (item.body ? JSON.stringify(item.body) : '');
const url = prospectData.audit_target_url || prospectData.website_url;
const prospectId = prospectData.prospect_id || `prospect-temp-${prospectData.row_index || 1}`;
const leadKey = prospectData.lead_key || prospectId;

const titleMatch = body.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const title = titleMatch ? titleMatch[1].trim() : null;

const metaDescMatch = body.match(/<meta[^>]+name=['"]description['"][^>]+content=['"]([\s\S]*?)['"]/i) ||
                      body.match(/<meta[^>]+content=['"]([\s\S]*?)['"][^>]+name=['"]description['"]/i);
const metaDescription = metaDescMatch ? metaDescMatch[1].trim() : null;

const viewportMatch = body.match(/<meta[^>]+name=['"]viewport['"]/i);
const hasViewport = Boolean(viewportMatch);

const sslActive = (url || '').startsWith('https://');
const isAccessible = statusCode >= 200 && statusCode < 400;

let errorCode = null;
if (!isAccessible) {
  if (statusCode) {
    errorCode = `HTTP_ERROR_${statusCode}`;
  } else if (item.error) {
    errorCode = item.error.code || item.error.message || 'NETWORK_ERROR';
  } else {
    errorCode = 'NETWORK_ERROR';
  }
}

const redirectCount = (item.redirectUrls && Array.isArray(item.redirectUrls)) ? item.redirectUrls.length : 0;
const responseTimeMs = typeof item.responseTime === 'number' ? Math.round(item.responseTime) : null;

const hypotheses = [];
if (!sslActive) {
  hypotheses.push({
    category: 'SECURITY_SSL',
    evidence: 'Sitio opera sin HTTPS por defecto',
    opportunity: 'Migración y securización con certificado SSL'
  });
}
if (!hasViewport) {
  hypotheses.push({
    category: 'MOBILE_RESPONSIVE',
    evidence: 'Falta etiqueta meta viewport para diseño responsivo',
    opportunity: 'Optimización de interfaz móvil (Mobile UX / RWD)'
  });
}
if (!metaDescription) {
  hypotheses.push({
    category: 'SEO_ONPAGE',
    evidence: 'No posee meta description declarada en HTML',
    opportunity: 'Optimización de snippets de búsqueda SEO on-page'
  });
}
if (!isAccessible) {
  hypotheses.push({
    category: 'SITE_HEALTH',
    evidence: `El sitio web no es accesible (${errorCode})`,
    opportunity: 'Recuperación de disponibilidad web y diagnóstico de hosting'
  });
}

return {
  json: {
    prospect_id: prospectId,
    lead_key: leadKey,
    initial_url: url,
    final_url: item.url || url,
    http_status: statusCode,
    redirect_count: redirectCount,
    response_time_ms: responseTimeMs,
    page_title: title,
    meta_description: metaDescription,
    has_viewport: hasViewport,
    ssl_active: sslActive,
    is_accessible: isAccessible,
    error_code: errorCode,
    commercial_hypotheses: hypotheses,
    raw_evidence: {
      status_code: statusCode,
      content_length: body.length,
      server: headers['server'] || null
    },
    is_synthetic_test: Boolean(prospectData.is_synthetic_test)
  }
};

// Manejo para URLs bloqueadas por SSRF
let prospectData = {};
try {
  prospectData = $('SSRF Security Filter').item.json;
} catch (e) {
  prospectData = $('SSRF Security Filter').first().json || {};
}
const prospectId = prospectData.prospect_id || `prospect-temp-${prospectData.row_index || 1}`;
const leadKey = prospectData.lead_key || prospectId;

return {
  json: {
    prospect_id: prospectId,
    lead_key: leadKey,
    initial_url: prospectData.audit_target_url || prospectData.website_url,
    final_url: null,
    http_status: null,
    redirect_count: 0,
    response_time_ms: null,
    page_title: null,
    meta_description: null,
    has_viewport: false,
    ssl_active: false,
    is_accessible: false,
    error_code: 'SSRF_BLOCKED',
    commercial_hypotheses: [],
    raw_evidence: { reason: prospectData.ssrf_block_reason },
    is_synthetic_test: Boolean(prospectData.is_synthetic_test)
  }
};

// ==============================================================================
// Preparar registro de auditoría estandarizado para website_audits
// ==============================================================================
const item = $input.item.json;
const timestamp = Date.now().toString(36);

function fnv(str, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  return ('00000000' + h.toString(16)).slice(-8);
}
function stableHash(str) { return fnv(str, 2166136261) + fnv(str, 3735928559); }

const normUrl = (item.initial_url || '').toLowerCase().replace(/\/+$/, '');
const stableIdempotencyKey = 'aud_' + stableHash(String(item.lead_key || item.prospect_id) + ':' + normUrl);

const auditId = item.is_synthetic_test
  ? `SYNTH-AUDIT-${timestamp}-${Math.random().toString(36).substring(2, 7)}-TESTONLY`
  : stableIdempotencyKey;

const auditRecord = {
  id: auditId,
  audit_id: auditId,
  prospect_id: String(item.prospect_id || ''),
  lead_key: String(item.lead_key || item.prospect_id || ''),
  audit_date: new Date().toISOString(),
  initial_url: item.initial_url || '',
  final_url: item.final_url || '',
  http_status: typeof item.http_status === 'number' ? item.http_status : null,
  redirect_count: typeof item.redirect_count === 'number' ? item.redirect_count : 0,
  response_time_ms: typeof item.response_time_ms === 'number' ? item.response_time_ms : null,
  page_title: item.page_title || '',
  meta_description: item.meta_description || '',
  has_viewport: Boolean(item.has_viewport),
  ssl_active: Boolean(item.ssl_active),
  is_accessible: Boolean(item.is_accessible),
  error_code: item.error_code || '',
  raw_evidence: JSON.stringify(item.raw_evidence || {}),
  commercial_hypotheses: JSON.stringify(item.commercial_hypotheses || []),
  is_synthetic_test: Boolean(item.is_synthetic_test)
};

return { json: auditRecord };

// ==============================================================================
// Terminal de Prueba Segura: Visualización en Output sin escribir en Data Tables
// ==============================================================================
const item = $input.item.json;
return {
  json: {
    ...item,
    _storage_status: 'DRY_RUN_NO_DATABASE_WRITE_PERFORMED',
    _verification_note: 'Registro sintético verificado con éxito en memoria. Cero escrituras en la base de datos real.'
  }
};

// ==============================================================================
// Éxito de Persistencia: Confirmación de registro escrito en website_audits
// ==============================================================================
let item = {};
try {
  item = ($input.item && $input.item.json) ? $input.item.json : ($input.first ? $input.first().json : {});
} catch (e) {
  item = ($input.first ? $input.first().json : {}) || {};
}
let auditPayload = {};
try {
  auditPayload = $('Prepare Persistence Payload').item.json;
} catch (e) {
  auditPayload = $('Prepare Persistence Payload').first().json || {};
}
return {
  json: {
    ...auditPayload,
    ...item,
    _storage_status: 'PERSISTED_REAL',
    persisted_table: 'website_audits',
    persisted_at: new Date().toISOString()
  }
};

// ==============================================================================
// Gestión Explícita de Error de Escritura: Nunca reportar éxito si falla la BD
// ==============================================================================
let errorItem = {};
try {
  errorItem = ($input.item && $input.item.json) ? $input.item.json : ($input.first ? $input.first().json : {});
} catch (e) {
  errorItem = ($input.first ? $input.first().json : {}) || {};
}
let auditPayload = {};
try {
  auditPayload = $('Prepare Persistence Payload').item.json;
} catch (e) {
  auditPayload = $('Prepare Persistence Payload').first().json || {};
}
const errorMsg = errorItem.error || errorItem.message || errorItem.description || 'Fallo al escribir en la Data Table website_audits';
return {
  json: {
    ...auditPayload,
    _storage_status: 'PERSISTENCE_FAILED',
    storage_error: String(errorMsg),
    failed_at: new Date().toISOString()
  }
};

// ==============================================================================
// Fin del Bucle: Resumen de Ejecución por Lote
// ==============================================================================
return {
  json: {
    status: 'BATCH_COMPLETED',
    completed_at: new Date().toISOString(),
    message: 'Todos los registros del lote han sido procesados de forma secuencial.'
  }
};
